#!/usr/bin/env node
/**
 * CMASTER design tokens compiler.
 *
 * Source of truth:  design/tokens.json   (same file the CMASTER design system publishes)
 * Outputs:          src/styles/cmaster-tokens.css   CSS custom properties, prefixed --cm-*
 *                   src/styles/cmasterTokens.ts     the same values as a typed object
 *
 * Usage:
 *   node scripts/tokens/build.mjs           write the outputs
 *   node scripts/tokens/build.mjs --check   exit 1 if the outputs are stale (used in CI)
 *
 * Do not edit the outputs by hand. Change design/tokens.json and rebuild.
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const SRC = resolve(ROOT, 'design/tokens.json');
const OUT_CSS = resolve(ROOT, 'src/styles/cmaster-tokens.css');
const OUT_TS = resolve(ROOT, 'src/styles/cmasterTokens.ts');
const PREFIX = 'cm';

const tokens = JSON.parse(readFileSync(SRC, 'utf8'));
const themes = tokens.color.themes.map((t) => t.id);
const [primaryTheme] = themes;

const cssName = (name) => `--${PREFIX}-${name.replace(/\./g, '\\.')}`;

/** "{other}" alias → var(--cm-other); anything else passes through. */
const resolveValue = (value) => {
  const alias = /^\{([A-Za-z0-9_.-]+)\}$/.exec(value);
  return alias ? `var(${cssName(alias[1])})` : value;
};

/** A token value for one theme; a missing theme inherits the primary theme's value. */
const valueFor = (token, theme) =>
  typeof token.value === 'string' ? token.value : (token.value[theme] ?? token.value[primaryTheme]);

/** Same, with aliases followed to a literal (for the TS output). */
const literalFor = (byName, token, theme, depth = 0) => {
  const raw = valueFor(token, theme);
  const alias = /^\{([A-Za-z0-9_.-]+)\}$/.exec(raw);
  if (!alias) return raw;
  const target = byName.get(alias[1]);
  if (!target || depth > 16) throw new Error(`Unresolvable alias ${raw} in ${token.name}`);
  return literalFor(byName, target, theme, depth + 1);
};

const themed = [...tokens.color.tokens, ...(tokens.shadow?.tokens ?? [])];
const plainFamilies = ['spacing', 'radius', 'zIndex'].filter((f) => tokens[f]);
const families = tokens.type.families;
const typeStyles = tokens.type.groups.flatMap((g) => g.styles.map((s) => ({ ...s, family: s.family ?? g.family })));

// ---------------------------------------------------------------- CSS
const header = `/* CMASTER design tokens. GENERATED by scripts/tokens/build.mjs from design/tokens.json. Do not edit by hand. */\n`;

const themeBlock = (theme, selector) => {
  // Later themes re-declare every per-theme value AND every alias: a custom property holding var(...)
  // is resolved where it is declared, so an alias declared only on :root would keep the dark value.
  const isAlias = (t) => typeof t.value === 'string' && /^\{.+\}$/.test(t.value);
  const lines = themed
    .filter((t) => theme === primaryTheme || typeof t.value !== 'string' || isAlias(t))
    .map((t) => `  ${cssName(t.name)}: ${resolveValue(valueFor(t, theme))};`);
  return `${selector} {\n${lines.join('\n')}\n  color-scheme: ${theme === 'light' ? 'light' : 'dark'};\n}\n`;
};

const rootLines = [
  ...plainFamilies.flatMap((f) => tokens[f].tokens.map((t) => `  ${cssName(t.name)}: ${t.value};`)),
  ...Object.entries(families).map(([k, v]) => `  ${cssName(`font-${k}`)}: ${v};`),
  ...typeStyles.map((s) => {
    const lh = s.lineHeight ?? 'normal';
    return `  ${cssName(`type-${s.name}`)}: ${s.fontWeight ?? 400} ${s.fontSize}/${lh} var(${cssName(`font-${s.family}`)});`;
  }),
  ...typeStyles
    .filter((s) => s.letterSpacing)
    .map((s) => `  ${cssName(`tracking-${s.name}`)}: ${s.letterSpacing};`),
];

// The IDE marks its root with data-mode="dark" | "light". Dark is the default.
const css =
  header +
  themeBlock(primaryTheme, `:root,\n[data-mode='${primaryTheme}']`) +
  themes
    .slice(1)
    .map((t) => `\n${themeBlock(t, `[data-mode='${t}']`)}`)
    .join('') +
  `\n:root {\n${rootLines.join('\n')}\n}\n`;

// ---------------------------------------------------------------- TS
const byName = new Map(themed.map((t) => [t.name, t]));
const colorsFor = (theme) =>
  Object.fromEntries(tokens.color.tokens.map((t) => [t.name, literalFor(byName, t, theme)]));
const shadowsFor = (theme) =>
  Object.fromEntries((tokens.shadow?.tokens ?? []).map((t) => [t.name, literalFor(byName, t, theme)]));
const campaignNames = [
  ...new Set(
    tokens.color.tokens
      .map((t) => /^campaign-([a-z]+)$/.exec(t.name)?.[1])
      .filter(Boolean),
  ),
];
const campaigns = Object.fromEntries(
  themes.map((theme) => [
    theme,
    Object.fromEntries(
      campaignNames.map((n) => [
        n,
        {
          accent: literalFor(byName, byName.get(`campaign-${n}`), theme),
          highlight: literalFor(byName, byName.get(`campaign-${n}-hi`), theme),
          onAccent: literalFor(byName, byName.get(`on-campaign-${n}`), theme),
        },
      ]),
    ),
  ]),
);

const data = {
  themes,
  color: Object.fromEntries(themes.map((t) => [t, colorsFor(t)])),
  shadow: Object.fromEntries(themes.map((t) => [t, shadowsFor(t)])),
  campaign: campaigns,
  font: families,
  type: Object.fromEntries(typeStyles.map(({ name, sample, usage, ...rest }) => [name, rest])),
  ...Object.fromEntries(
    plainFamilies.map((f) => [f, Object.fromEntries(tokens[f].tokens.map((t) => [t.name, t.value]))]),
  ),
};

const ts =
  `/* CMASTER design tokens. GENERATED by scripts/tokens/build.mjs from design/tokens.json. Do not edit by hand. */\n\n` +
  `/** Every CMASTER token value, per theme. Prefer the --cm-* CSS variables in styles; use this only where CSS cannot reach (canvas, SVG export, posters). */\n` +
  `export const cmasterTokens = ${JSON.stringify(data, null, 2)} as const;\n\n` +
  `export type CmasterTheme = (typeof cmasterTokens.themes)[number];\n` +
  `export type CmasterColorToken = keyof (typeof cmasterTokens.color)['${primaryTheme}'];\n` +
  `export type CmasterCampaign = keyof (typeof cmasterTokens.campaign)['${primaryTheme}'];\n\n` +
  `/** CSS variable reference for a token name, e.g. cmVar('brand-500') → 'var(--cm-brand-500)'. */\n` +
  `export const cmVar = (name: string): string => \`var(--${PREFIX}-\${name})\`;\n`;

// ---------------------------------------------------------------- write / check
const outputs = [
  [OUT_CSS, css],
  [OUT_TS, ts],
];

if (process.argv.includes('--check')) {
  const stale = outputs.filter(([file, text]) => !existsSync(file) || readFileSync(file, 'utf8') !== text);
  if (stale.length) {
    console.error(
      `Design tokens are out of date: ${stale.map(([f]) => f.replace(ROOT + '/', '')).join(', ')}\n` +
        'Run `npm run tokens:build` and commit the result.',
    );
    process.exit(1);
  }
  console.log('Design tokens are up to date.');
} else {
  for (const [file, text] of outputs) writeFileSync(file, text);
  console.log(`Wrote ${outputs.map(([f]) => f.replace(ROOT + '/', '')).join(', ')}`);
}
